import {dataTypes,dataDefault} from './data-assets.js';
import {assetTypes,validAsset} from './asset-documents.js';
import {inputActionDefaults} from './input-actions.js';
import {icon,assetIcon} from './icons.js';
import {materialLayersFields,editMaterialLayers} from './material-layers-ui.js';
import {materialLayerParameters,materialDefaults,materialParameters,resolveMaterialAsset} from './material-runtime.js';
export const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeText,options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
const assetOptions=(files,kinds,value)=>options([['','없음'],...files.filter(file=>kinds.includes(file.kind)||file.path===value).map(file=>[file.path,file.name])],value);
const field=(label,path,value,{type='number',min,max,step='.01'}={})=>`<label>${esc(label)}<input data-editor-field="${path}" type="${type}" ${type==='checkbox'?(value?'checked':''):`value="${esc(value)}"`} ${min===undefined?'':`min="${min}"`} ${max===undefined?'':`max="${max}"`} step="${step}" aria-label="${esc(label)}"></label>`;
const vectorField=(label,path,value)=>`<label>${esc(label)}<span class="asset-vector-fields">${value.map((v,i)=>`<input type="number" step=".05" value="${v}" data-editor-field="${path}.${i}" aria-label="${esc(label)} ${'XYZW'[i]}">`).join('')}</span></label>`;
const assetField=(label,path,value,files,kinds)=>`<label>${esc(label)}<select data-editor-field="${path}">${assetOptions(files,kinds,value)}</select></label>`;
export function renderDataEditor(element,doc,files,hooks){
  const d=doc.data,kind=doc.kind;element.hbAssetDocument=doc;
  element.innerHTML=`<header class="asset-editor-heading"><span class="asset-symbol ${kind}">${icon(assetIcon(kind))}</span><div><small>${assetTypes[kind].label}</small><h2>${esc(d.name)}</h2></div></header><div class="asset-form"></div>`;
  const form=element.querySelector('.asset-form');
  if(kind==='inputaction')form.innerHTML=`<section><h3>값</h3><label>자료형<select data-field="valueType">${options([['bool','Digital · Boolean'],['float','Axis 1D · Float'],['vec2','Axis 2D · Vector2'],['vec3','Axis 3D · Vector3']],d.valueType)}</select></label><label>데드존<input data-field="deadZone" type="number" value="${d.deadZone}" min="0" max="1" step=".05"></label></section><section><h3>트리거</h3><label>방식<select data-field="trigger">${options([['pressed','Pressed · 누르기'],['held','Down · 유지'],['released','Released · 떼기'],['hold','Hold · 길게 누르기'],['holdRelease','Hold And Release'],['tap','Tap · 짧게 누르기'],['doubleTap','Double Tap · 두 번 누르기'],['pulse','Pulse · 반복']],d.trigger)}</select></label>${['hold','holdRelease'].includes(d.trigger)?field('유지 시간','holdTime',d.holdTime??inputActionDefaults.holdTime,{min:.001,max:60})+field('한 번만 발동','oneShot',d.oneShot??inputActionDefaults.oneShot,{type:'checkbox'}):''}${['tap','doubleTap'].includes(d.trigger)?field('탭 최대 시간','tapTime',d.tapTime??inputActionDefaults.tapTime,{min:.001,max:60}):''}${d.trigger==='doubleTap'?field('탭 사이 간격','tapInterval',d.tapInterval??inputActionDefaults.tapInterval,{min:.001,max:60}):''}${d.trigger==='pulse'?field('반복 간격','pulseInterval',d.pulseInterval??inputActionDefaults.pulseInterval,{min:.001,max:60}):''}${assetField('조합 액션','chordAction',d.chordAction||'',files.filter(f=>f.path!==doc.path),['inputaction'])}<label>입력 소비<input type="checkbox" data-field="consumeInput" ${d.consumeInput?'checked':''}></label></section><section><h3>모디파이어</h3>${(d.modifiers||[]).map((m,i)=>`<div class="input-modifier" data-index="${i}"><div class="form-section-heading"><strong>${esc(m.type)}</strong><button data-modifier-up="${i}" ${i?'':'disabled'} aria-label="위로">↑</button><button data-modifier-down="${i}" ${i<(d.modifiers.length-1)?'':'disabled'} aria-label="아래로">↓</button><button data-modifier-remove="${i}" aria-label="삭제">${icon('close')}</button></div>${m.axes?vectorField('축','modifiers.'+i+'.axes',m.axes):m.type==='swizzle'?`<label>축 순서<select data-editor-field="modifiers.${i}.order">${options(['xyz','xzy','yxz','yzx','zxy','zyx'].map(v=>[v,v.toUpperCase()]),m.order)}</select></label>`:m.type==='exponential'?field('지수','modifiers.'+i+'.exponent',m.exponent,{min:.01,max:10}):''}</div>`).join('')}<div class="form-section-heading"><select data-new-modifier aria-label="모디파이어 종류">${options(['scale','negate','swizzle','normalize','exponential'].map(v=>[v,v]),'scale')}</select><button data-modifier-add>${icon('plus')} 추가</button></div></section>`;
  if(kind==='inputmapping')form.innerHTML=`<section><h3>컨텍스트</h3><label>우선순위<input type="number" data-field="priority" min="-10000" max="10000" value="${d.priority}"></label></section><section><div class="form-section-heading"><h3>키 매핑</h3><button data-add>${icon('plus')} 매핑 추가</button></div><div class="mapping-columns"><span>Input Action</span><span>키</span><span>축</span><span>배율</span><span></span></div>${d.mappings.map((m,i)=>`<div class="mapping-row" data-index="${i}"><select data-map="action" aria-label="${i+1} 입력 액션">${options([['','선택'],...files.filter(f=>f.kind==='inputaction').map(f=>[f.path,f.name.replace('.hbinputaction.json','')])],m.action)}</select><input data-map="key" value="${esc(m.key)}" aria-label="${i+1} 키" maxlength="40"><select data-map="axis" aria-label="${i+1} 축">${options([['0','X'],['1','Y'],['2','Z']],String(m.axis))}</select><input type="number" step=".1" min="-100" max="100" data-map="scale" value="${m.scale}" aria-label="${i+1} 배율"><button data-remove="${i}" aria-label="${i+1} 매핑 삭제">${icon('close')}</button></div>`).join('')}</section>`;
  if(kind==='data'){
    const table=!!d.rows,cell=(type,value,attrs)=>type==='json'?'<textarea '+attrs+' aria-label="JSON 값">'+esc(JSON.stringify(value))+'</textarea>':'<input '+attrs+' type="'+(type==='float'?'number':type==='bool'?'checkbox':'text')+'" '+(type==='bool'?(value?'checked':''):'value="'+esc(value)+'"')+' aria-label="값">';
    form.innerHTML='<section><div class="form-section-heading"><h3>'+ (table?'데이터 표':'데이터 속성')+'</h3><button data-data-mode>'+ (table?'속성으로':'표로')+'</button><button data-add>'+icon('plus')+' '+(table?'열':'속성')+'</button>'+(table?'<button data-row-add>'+icon('plus')+' 행</button>':'')+'</div>'+(table?'<div class="data-table-scroll"><table class="asset-data-table"><thead><tr><th>행 ID</th>'+d.columns.map((c,i)=>'<th><input data-column="'+i+'" value="'+esc(c.name)+'" aria-label="열 이름"><select data-column-type="'+i+'">'+options(dataTypes.map(t=>[t,t]),c.type)+'</select><button data-column-remove="'+i+'" aria-label="열 삭제">'+icon('close')+'</button></th>').join('')+'<th></th></tr></thead><tbody>'+Object.entries(d.rows).map(([id,row])=>'<tr><td><input data-row-id="'+esc(id)+'" value="'+esc(id)+'" aria-label="행 ID"></td>'+d.columns.map(c=>'<td>'+cell(c.type,row[c.name],'data-cell-row="'+esc(id)+'" data-cell-column="'+esc(c.name)+'"')+'</td>').join('')+'<td><button data-row-remove="'+esc(id)+'" aria-label="행 삭제">'+icon('close')+'</button></td></tr>').join('')+'</tbody></table></div>':d.fields.map((f,i)=>'<div class="data-field-row" data-index="'+i+'"><input data-value="name" value="'+esc(f.name)+'" aria-label="속성 이름"><select data-value="type">'+options(dataTypes.map(t=>[t,t]),f.type)+'</select>'+cell(f.type,f.value,'data-value="value"')+'<button data-remove="'+i+'" aria-label="속성 삭제">'+icon('close')+'</button></div>').join(''))+'</section>';
  }
  if(kind==='physicalmaterial')form.innerHTML=`<section><h3>접촉</h3>${field('마찰','friction',d.friction,{min:0,max:10})}${field('반발','restitution',d.restitution,{min:0,max:1})}${field('밀도','density',d.density,{min:.001,max:10000})}${['frictionCombine','restitutionCombine'].map((key,i)=>`<label>${i?'반발':'마찰'} 결합<select data-editor-field="${key}">${options([['average','Average · 평균'],['min','Min · 최솟값'],['max','Max · 최댓값'],['multiply','Multiply · 곱하기']],d[key])}</select></label>`).join('')}</section>`;
  if(kind==='gameconfig')form.innerHTML=`<section><h3>시작</h3>${assetField('시작 레벨','startupScene',d.startupScene,files,['scene'])}${assetField('시작 블루프린트','startupBlueprint',d.startupBlueprint,files,['blueprint'])}${assetField('입력 매핑','defaultInputMapping',d.defaultInputMapping,files,['inputmapping'])}<label>공간<select data-editor-field="dimension">${options([['3d','3D'],['2d','2D']],d.dimension||'3d')}</select></label></section><section><h3>게임플레이 클래스</h3>${[['gameInstance','GameInstance'],['gameMode','GameMode'],['gameState','GameState'],['defaultController','PlayerController'],['playerState','PlayerState'],['defaultPawn','Pawn / Character']].map(([key,label])=>assetField(label,key,d[key],key==='gameInstance'?files.filter(f=>f.kind==='blueprint'||f.kind==='code'&&/\.(h|hpp)$/.test(f.path)):files,key==='gameInstance'?['blueprint','code']:['blueprint'])).join('')}${vectorField('생성 위치','spawnPosition',d.spawnPosition)}${field('플레이어 자동 생성','autoSpawnPlayer',d.autoSpawnPlayer,{type:'checkbox'})}</section><section><h3>물리</h3>${vectorField('중력','gravity',d.gravity)}${field('고정 시간 간격','fixedDeltaTime',d.fixedDeltaTime,{min:.001,max:1,step:'.001'})}${field('최대 서브스텝','maxSubsteps',d.maxSubsteps,{min:1,max:64,step:'1'})}</section><section><h3>게임 창</h3>${field('너비','window.width',d.window.width,{min:320,max:16384,step:'1'})}${field('높이','window.height',d.window.height,{min:320,max:16384,step:'1'})}${field('전체 화면','window.fullscreen',d.window.fullscreen,{type:'checkbox'})}${field('수직 동기화','window.vsync',d.window.vsync,{type:'checkbox'})}</section>`;
  if(kind==='audioasset')form.innerHTML=`<section><h3>재생</h3>${assetField('클립','clip',d.clip,files,['media'])}${field('볼륨','volume',d.volume,{min:0,max:4})}${field('피치','pitch',d.pitch,{min:.1,max:4})}${field('반복','loop',d.loop,{type:'checkbox'})}${field('자동 재생','autoplay',d.autoplay,{type:'checkbox'})}<div class="asset-audio-preview"></div></section><section><h3>라우팅</h3>${assetField('믹서','mixer',d.mixer||'',files,['audiomixer'])}${field('출력 버스 ID','bus',d.bus||'master',{type:'text'})}</section><section><h3>공간</h3>${field('3D 공간 음향','spatial',d.spatial,{type:'checkbox'})}${field('기준 거리','refDistance',d.refDistance,{min:.01,max:100000})}${field('최대 거리','maxDistance',d.maxDistance,{min:.01,max:100000})}${field('거리 감쇠','rolloff',d.rolloff,{min:0,max:100000})}</section>`;
  if(kind==='audioasset'&&d.clip){const audio=document.createElement('audio');audio.controls=true;audio.src='/api/file?path='+encodeURIComponent(d.clip);audio.volume=Math.min(1,d.volume);audio.playbackRate=d.pitch;audio.loop=d.loop;form.querySelector('.asset-audio-preview').append(audio);}
  if(kind==='prefab')form.innerHTML=`<section><div class="form-section-heading"><h3>오브젝트</h3><button data-prefab-add>${icon('plus')} 큐브 추가</button>${hooks.captureSelection?'<button data-prefab-capture>장면 선택 가져오기</button>':''}${hooks.instantiate?'<button data-prefab-place>장면에 배치</button>':''}</div>${d.objects.map((object,i)=>`<details class="prefab-object" ${i===0?'open':''}><summary>${esc(object.name)} · ${esc(object.kind)}</summary>${field('이름','objects.'+i+'.name',object.name,{type:'text'})}${vectorField('위치','objects.'+i+'.position',object.position)}${vectorField('회전','objects.'+i+'.rotation',object.rotation)}${vectorField('크기','objects.'+i+'.scale',object.scale)}${assetField('머테리얼','objects.'+i+'.materialAsset',object.materialAsset||'',files,['material','materialinstance'])}${assetField('블루프린트','objects.'+i+'.blueprintAsset',object.blueprintAsset||'',files,['blueprint'])}${object.id!==d.root?`<button data-prefab-remove="${i}">오브젝트 삭제</button>`:''}</details>`).join('')}</section>`;
  if(kind==='materialinstance'){
    const descriptors=doc.view.parentParameters?.path===d.parent?doc.view.parentParameters.items:[],known=new Set(descriptors.map(item=>item.name)),parameters=[...descriptors.filter(p=>!p.scope),...Object.entries(d.parameters).filter(([name])=>!known.has(name)).map(([name,value])=>({name,value,type:Array.isArray(value)?'vec3':typeof value==='string'?'texture':'float'}))];
    form.innerHTML=`<section><h3>부모</h3>${assetField('머테리얼','parent',d.parent,files,['material','materialinstance'])}</section><section><h3>파라미터</h3>${parameters.map(item=>{const enabled=Object.hasOwn(d.parameters,item.name),value=enabled?d.parameters[item.name]:item.value;return `<div class="material-instance-parameter"><label class="parameter-override"><input type="checkbox" data-parameter-override="${esc(item.name)}" ${enabled?'checked':''}>${esc(item.name)}</label>${item.type==='vec3'?vectorField('값','parameters.'+item.name,value):item.type==='texture'?assetField('텍스처','parameters.'+item.name,value,files,['texture']):field('값','parameters.'+item.name,value)}${enabled?`<button data-remove-parameter="${esc(item.name)}" aria-label="${esc(item.name)} 재정의 해제">${icon('close')}</button>`:''}</div>`;}).join('')}</section><section><h3>표면 재정의</h3>${[['color','기본 색상','color'],['roughness','거칠기','number'],['metalness','금속성','number'],['emissive','발광 색상','color'],['emissiveIntensity','발광 강도','number'],['opacity','불투명도','number'],['clearcoat','코팅','number'],['transmission','투과','number'],['ior','굴절률','number'],['doubleSided','양면','checkbox']].map(([key,label,type])=>`<div class="material-instance-surface"><label class="parameter-override"><input type="checkbox" data-surface-override="${key}" ${Object.hasOwn(d.surfaceOverrides,key)?'checked':''}>${label}</label>${field('값','surfaceOverrides.'+key,d.surfaceOverrides[key]??materialDefaults[key],{type})}</div>`).join('')}<label>혼합 모드<select data-editor-field="surfaceOverrides.blendMode">${options([['opaque','Opaque · 불투명'],['masked','Masked · 마스크'],['translucent','Translucent · 반투명']],d.surfaceOverrides.blendMode||'opaque')}</select></label></section>`;
    const surfaceSection=form.lastElementChild;if(!parameters.length)form.children[1].remove();
    const inherited=doc.view.parentParameters?.path===d.parent?doc.view.parentParameters.stacks||{}:{},stacks={...inherited,...d.layerStacks},layerParameters=doc.view.layerParameters?.items||[];
    for(const [id,layers] of Object.entries(stacks)){const section=document.createElement('section');section.className='material-instance-layers';section.dataset.layerStack=id;section.innerHTML=`<h3>레이어 스택</h3><label class="parameter-override"><input type="checkbox" data-layer-stack-override="${id}" ${Object.hasOwn(d.layerStacks||{},id)?'checked':''}>스택 재정의</label>${materialLayersFields(layers,files,layerParameters)}`;form.insertBefore(section,surfaceSection);}
    const key=()=>JSON.stringify([doc.view.materialEpoch||0,doc.data.parent,{...(doc.view.parentParameters?.path===doc.data.parent?doc.view.parentParameters.stacks:{}),...doc.data.layerStacks}]),signature=key();if(d.parent&&hooks.readAsset&&doc.view.layerParameters?.signature!==signature&&doc.view.loadingLayers!==signature){doc.view.loadingLayers=signature;materialLayerParameters(stacks,hooks.readAsset).then(items=>{if(element.hbAssetDocument!==doc||key()!==signature)return;doc.view.layerParameters={signature,items};renderDataEditor(element,doc,files,hooks);}).catch(error=>{if(element.hbAssetDocument!==doc||key()!==signature)return;doc.view.layerParameters={signature,items:[]};hooks.error(error.message);}).finally(()=>{if(doc.view.loadingLayers===signature)delete doc.view.loadingLayers;});}
    const epoch=doc.view.materialEpoch||0;if(d.parent&&hooks.readAsset&&(doc.view.parentParameters?.path!==d.parent||doc.view.parentParameters.epoch!==epoch)&&(doc.view.loadingParent?.path!==d.parent||doc.view.loadingParent.epoch!==epoch)){const parent=d.parent,ticket={path:parent,epoch};doc.view.loadingParent=ticket;const fresh=()=>element.hbAssetDocument===doc&&doc.data.parent===parent&&(doc.view.materialEpoch||0)===epoch;hooks.readAsset(parent).then(data=>resolveMaterialAsset(data,hooks.readAsset)).then(data=>{if(!fresh())return;doc.view.parentParameters={path:parent,epoch,items:materialParameters(data),surface:data.surface,stacks:data.layerStacks||{}};renderDataEditor(element,doc,files,hooks);}).catch(error=>{if(fresh())hooks.error(error.message);}).finally(()=>{if(doc.view.loadingParent===ticket)delete doc.view.loadingParent;});}
  }
  const edit=fn=>{const next=structuredClone(doc.data);fn(next);if(!validAsset(kind,next)){hooks.error('값이나 중복된 이름을 확인하세요.');renderDataEditor(element,doc,files,hooks);return;}if(JSON.stringify(next)===JSON.stringify(doc.data))return;hooks.before();doc.data=next;hooks.change();renderDataEditor(element,doc,files,hooks);};
  element.onchange=e=>{try{const input=e.target,field=input.dataset.field;if(input.dataset.layerStackOverride){edit(data=>{data.layerStacks??={};if(input.checked)data.layerStacks[input.dataset.layerStackOverride]=structuredClone(doc.view.parentParameters?.stacks[input.dataset.layerStackOverride]||[]);else delete data.layerStacks[input.dataset.layerStackOverride];});return;}if(input.closest('.material-layer-stack')){const id=input.closest('[data-layer-stack]').dataset.layerStack;edit(data=>{data.layerStacks??={};data.layerStacks[id]??=structuredClone(doc.view.parentParameters?.stacks[id]||[]);editMaterialLayers(data.layerStacks[id],input,doc.view.layerParameters?.items||[]);});return;}
    if(kind==='data'&&d.rows&&(input.dataset.cellRow!==undefined||input.dataset.column!==undefined||input.dataset.columnType!==undefined||input.dataset.rowId!==undefined)){
      try{edit(data=>{if(input.dataset.cellRow!==undefined){const column=data.columns.find(c=>c.name===input.dataset.cellColumn);data.rows[input.dataset.cellRow][column.name]=column.type==='json'?JSON.parse(input.value):column.type==='float'?Number(input.value):column.type==='bool'?input.checked:input.value;}else if(input.dataset.column!==undefined){const c=data.columns[Number(input.dataset.column)],old=c.name;c.name=input.value;for(const row of Object.values(data.rows)){row[c.name]=row[old];delete row[old];}}else if(input.dataset.columnType!==undefined){const c=data.columns[Number(input.dataset.columnType)];c.type=input.value;for(const row of Object.values(data.rows))row[c.name]=structuredClone(dataDefault(c.type));}else {const old=input.dataset.rowId;if(input.value!==old){if(Object.hasOwn(data.rows,input.value))throw Error('행 ID가 겹쳐요.');data.rows[input.value]=data.rows[old];delete data.rows[old];}}});}catch(error){hooks.error(error.message);}return;
    }if(input.dataset.editorField)edit(data=>{const path=input.dataset.editorField.split('.'),last=path.pop();let target=data;for(const key of path){target[key]??={};target=target[key];}target[last]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;});else if(input.dataset.parameterOverride)edit(data=>{const key=input.dataset.parameterOverride;if(input.checked)data.parameters[key]=structuredClone(doc.view.parentParameters?.items.find(item=>item.name===key)?.value??.5);else delete data.parameters[key];});else if(input.dataset.surfaceOverride)edit(data=>{const key=input.dataset.surfaceOverride;if(input.checked)data.surfaceOverrides[key]=structuredClone(doc.view.parentParameters?.surface[key]??materialDefaults[key]);else delete data.surfaceOverrides[key];});else if(field)edit(d=>d[field]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value);else if(input.dataset.map){const i=Number(input.closest('[data-index]').dataset.index),key=input.dataset.map;edit(d=>d.mappings[i][key]=['axis','scale'].includes(key)?Number(input.value):input.value);}else if(input.dataset.value){const i=Number(input.closest('[data-index]').dataset.index),key=input.dataset.value;edit(d=>{const f=d.fields[i];f[key]=key==='value'?f.type==='bool'?input.checked:f.type==='float'?Number(input.value):f.type==='json'?JSON.parse(input.value):input.value:input.value;if(key==='type')f.value=structuredClone(dataDefault(input.value));});}}catch(error){hooks.error?.(error.message);renderDataEditor(element,doc,files,hooks);}};
  element.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.layerOpen){hooks.openAsset?.(b.dataset.layerOpen);return;}if(b.dataset.layerAction){const id=b.closest('[data-layer-stack]').dataset.layerStack;edit(data=>{data.layerStacks??={};data.layerStacks[id]??=structuredClone(doc.view.parentParameters?.stacks[id]||[]);editMaterialLayers(data.layerStacks[id],b,doc.view.layerParameters?.items||[]);});return;}if(b.hasAttribute('data-modifier-add')){edit(data=>{data.modifiers??=[];const type=element.querySelector('[data-new-modifier]').value;data.modifiers.push({type,...(['scale','negate'].includes(type)?{axes:[1,1,1]}:type==='swizzle'?{order:'yxz'}:type==='exponential'?{exponent:2}:{})});});return;}if(b.dataset.modifierRemove!==undefined){edit(data=>data.modifiers.splice(Number(b.dataset.modifierRemove),1));return;}if(b.dataset.modifierUp!==undefined||b.dataset.modifierDown!==undefined){const up=b.dataset.modifierUp!==undefined,index=Number(up?b.dataset.modifierUp:b.dataset.modifierDown),to=index+(up?-1:1);edit(data=>{[data.modifiers[index],data.modifiers[to]]=[data.modifiers[to],data.modifiers[index]];});return;}if(b.dataset.removeParameter){edit(data=>delete data.parameters[b.dataset.removeParameter]);return;}if(b.hasAttribute('data-prefab-add')){edit(data=>data.objects.push({id:crypto.randomUUID(),name:'Cube '+data.objects.length,kind:'cube',group:'PREFAB',position:[0,0,0],rotation:[0,0,0],scale:[1,1,1],visible:true}));return;}if(b.dataset.prefabRemove!==undefined){edit(data=>data.objects.splice(Number(b.dataset.prefabRemove),1));return;}if(b.hasAttribute('data-prefab-capture')){edit(data=>{const objects=hooks.captureSelection();if(!objects?.length)return;data.objects=structuredClone(objects);data.root=data.objects[0].id;});return;}if(b.hasAttribute('data-prefab-place')){hooks.instantiate?.(doc);return;}if(kind==='data'){if(b.hasAttribute('data-data-mode')){edit(data=>{if(data.rows){data.fields=data.columns.map(c=>({...c,value:structuredClone(Object.values(data.rows)[0]?.[c.name]??dataDefault(c.type))}));delete data.rows;delete data.columns;}else{data.columns=data.fields.map(({name,type})=>({name,type}));data.rows={Row1:Object.fromEntries(data.fields.map(f=>[f.name,f.value]))};delete data.fields;}});return;}if(d.rows){edit(data=>{if(b.hasAttribute('data-add')){let i=1;while(data.columns.some(c=>c.name==='Column'+i))i++;data.columns.push({name:'Column'+i,type:'float'});for(const row of Object.values(data.rows))row['Column'+i]=0;}else if(b.hasAttribute('data-row-add')){let i=1;while(Object.hasOwn(data.rows,'Row'+i))i++;data.rows['Row'+i]=Object.fromEntries(data.columns.map(c=>[c.name,structuredClone(dataDefault(c.type))]));}else if(b.dataset.rowRemove!==undefined)delete data.rows[b.dataset.rowRemove];else if(b.dataset.columnRemove!==undefined){const [c]=data.columns.splice(Number(b.dataset.columnRemove),1);for(const row of Object.values(data.rows))delete row[c.name];}});return;}}const key=kind==='inputmapping'?'mappings':'fields';if(b.hasAttribute('data-add'))edit(d=>{if(key==='mappings')d.mappings.push({action:'',key:'E',axis:0,scale:1});else{let index=1;while(d.fields.some(f=>f.name==='Value'+index))index++;d.fields.push({name:'Value'+index,type:'float',value:0});}});else if(b.dataset.remove!==undefined)edit(d=>d[key].splice(Number(b.dataset.remove),1));};
}
export function closeChoice(name){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='close-document-dialog';dialog.innerHTML=`<h2>${esc(name)} 저장</h2><p>저장하지 않은 변경 사항이 있어요.</p><footer><button data-result="cancel">취소</button><button data-result="discard">저장 안 함</button><button data-result="save" class="primary-button">저장</button></footer>`;document.body.append(dialog);let result='cancel';dialog.onclick=e=>{if(e.target.dataset.result){result=e.target.dataset.result;dialog.close();}};dialog.onclose=()=>{dialog.remove();resolve(result);};dialog.showModal();});}
